    /*
     * Add to the Items
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Order
     */
    public Order addToItems( UUID parentId, OrderItem addTo ) {
	    LOGGER.info("handling AssignItemsToOrderEvent - " );
	    
	    Order parentEntity = repository.findById(parentId).get();
	    OrderItem child = registry.project( OrderItem.class, addTo.getOrderItemId());
	    
	    parentEntity.getItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Items
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Order
     */
	public Order removeFromItems( UUID parentId, OrderItem removeFrom ) {
	    LOGGER.info("handling RemoveItemsFromOrderEvent " );
	
	    Order parentEntity = repository.findById(parentId).get();
	    OrderItem child = registry.project( OrderItem.class, removeFrom.getOrderItemId());
	    
	    parentEntity.getItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Order via an FindOrderQuery
     * @return 	query	FindOrderQuery
     */
    @SuppressWarnings("unused")
    public Order find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Order - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Orders
     *
     * @param	query	FindAllOrderQuery 
     * @return 	List<Order> 
     */
    @SuppressWarnings("unused")
    public List<Order> findAll( FindAllOrderQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Order - {0}", exc.getMessage() );
    	}
    	return null;
    }


